74	// Wrapper around the type information query for whether DSL function "f"
75	// requires an implicit token calling convention, including overrides provided
76	// via ConvertOptions.
77	bool GetRequiresImplicitToken(const dslx::Function& f, ImportData* import_data,
78	                              const ConvertOptions& options);
