80	// Creates a function that wraps up `implicit_token_f`.
81	//
82	// Precondition: `implicit_token_f` must use the "implicit token" calling
83	// convention, see `CallingConvention` for details.
84	//
85	// The wrapped function exposes the implicit token function as if it were a
86	// normal function, so it can be called by the outside world in a typical
87	// fashion as an entry point (e.g. the IR JIT, Verilog module signature, etc).
88	absl::StatusOr<xls::Function*> EmitImplicitTokenEntryWrapper(
89	    xls::Function* implicit_token_f, dslx::Function* dslx_function, bool is_top,
90	    PackageInterfaceProto* interface_proto,
