93	// Bundles together a package pointer with a supplementary map we keep that
94	// shows the DSLX function that led to IR functions in the package.
95	struct PackageData {
96	  PackageConversionData* conversion_info;
97	  absl::flat_hash_map<xls::FunctionBase*, dslx::Function*> ir_to_dslx;
98	  absl::flat_hash_map<std::pair<const dslx::Function*, ParametricEnv>,
99	                      xls::Proc*>
100	      callee_to_ir_proc;
101	
102	  absl::btree_map<InterpValue, xls::Proc*>
103	      canonical_proc_def_initializer_to_ir_proc;
104	  absl::flat_hash_set<xls::Function*> wrappers;
105	};
