107	// A function that creates/returns a predicate value -- since this is used
108	// frequently when making "chained" predicates through control constructs, we
109	// give it an alias.
110	using PredicateFun = std::function<BValue()>;
111	
112	// If the function being converted has an implicit token; e.g. caused by
113	// the need to have `assert` IR ops (via DSLX `fail!`), it is created here.
114	// Whenever we have an entry token we also have an associated "was I activated"
115	// boolean which will help guard the associated assertion(s).
116	//
117	// Similarly when there's an entry token we need to keep track of current
118	// control predicates, and join all the assertion tokens together at the end,
119	// into the output token.
120	struct ImplicitTokenData {
121	  BValue entry_token;
122	  BValue activated;
123	  PredicateFun create_control_predicate;
124	  // Used for sequencing by both fail! and cover! ops.
125	  std::vector<BValue> control_tokens;
126	};
