128	// Helper type that creates XLS IR for a function -- this is done within a
129	// Package, given a DSLX AST, its type information, and an entry point function.
130	//
131	// It mainly encapsulates DSLX=>IR mapping `node_to_ir_` used for resolution of
132	// FunctionBuilder values (BValue) in the conversion rules.
133	//
134	// Implementation note: these are "throwaway objects"; i.e. instantiate them
135	// once to visit a single function and then discard. It exists mostly to avoid
136	// needing to thread conversion state between a bunch of on-the-wall functions.
137	//
138	// A function's external constant dependencies (e.g. if a function refers to a
139	// module-level constant as a free variable) have to be noted from the outside
140	// world via calls to `AddConstantDep()`.
141	//
142	// Implementation note: we don't tack a `Function*` attribute on here because we
143	// use this same facility for translating the body of a for loop into a function
144	// -- for that "anonymous function" there's not a direct correspondence to a
145	// DSLX function.
146	class FunctionConverter {
147	 public:
148	  FunctionConverter(PackageData& package_data, Module* module,
149	                    ImportData* import_data, ConvertOptions options,
150	                    ProcConversionData* proc_data, ChannelScope* channel_scope,
151	                    bool is_top);
152	
153	  // Main entry point to request conversion of the DSLX function "f" to an IR
154	  // function.
155	  absl::Status HandleFunction(Function* node, TypeInfo* type_info,
156	                              const ParametricEnv* parametric_env);
157	
158	  absl::Status HandleProcNextFunction(const ConversionRecord& record,
159	                                      ImportData* import_data,
160	                                      ProcConversionData* proc_data);
161	
162	  absl::Status ConvertProcDef(const ProcDef* proc_def,
163	                              const InterpValue& canonical_initializer_value,
164	                              ProcId proc_id, TypeInfo* constructor_ti,
165	                              TypeInfo* next_ti, const ParametricEnv& env);
166	
167	  // Notes a constant-definition dependency for the function (so it can
168	  // participate in the IR conversion).
169	  void AddConstantDep(ConstantDef* constant_def);
170	
171	 private:
172	  // Helper class used for dispatching to IR conversion methods.
173	  friend class FunctionConverterVisitor;
174	
175	  friend struct ScopedTypeInfoSwap;
176	
177	  // Helper class used for chaining on/off control predicates.
178	  friend class ScopedControlPredicate;
179	
180	  // Contains/returns the pertinent information about a range expression (either
181	  // a Range node or the range() builtin).
182	  struct RangeData {
183	    int64_t start_value;
184	    int64_t trip_count;
185	    int64_t bit_width;
186	  };
187	
188	  const FileTable& file_table() const { return import_data_->file_table(); }
189	
190	  // Wraps up a type so it is (token, u1, type).
191	  static xls::Type* WrapIrForImplicitTokenType(xls::Type* type,
192	                                               Package* package) {
193	    xls::Type* token_type = package->GetTokenType();
194	    xls::Type* u1_type = package->GetBitsType(1);
195	    return package->GetTupleType({token_type, u1_type, type});
196	  }
197	
198	  // Helper function used for adding a parameter type in for-loops and similar.
199	  BValue AddParam(std::string_view name, xls::Type* type) {
200	    CHECK(function_proto_);
201	    auto* param_proto = function_proto_.value()->add_parameters();
202	    param_proto->set_name(name);
203	    *param_proto->mutable_type() = type->ToProto();
204	    // This is only for internal 'for-loop' and similar impl functions so they
205	    // won't ever be emitted as verilog.
206	    return function_builder_->Param(name, type);
207	  }
208	
209	  // Helper function used for adding a parameter type wrapped up in a
210	  // token/activation boolean.
211	  BValue AddTokenWrappedParam(xls::Type* type) {
212	    BuilderBase* fb = function_builder_.get();
213	    xls::Type* wrapped_type = WrapIrForImplicitTokenType(type, package());
214	    BValue param = fb->Param("__token_wrapped", wrapped_type);
215	    BValue entry_token = fb->TupleIndex(param, 0);
216	    BValue activated = fb->TupleIndex(param, 1);
217	    auto create_control_predicate = [activated] { return activated; };
218	    implicit_token_data_ =
219	        ImplicitTokenData{entry_token, activated, create_control_predicate};
220	    BValue unwrapped = fb->TupleIndex(param, 2);
221	    CHECK(function_proto_);
222	    auto* param_proto = function_proto_.value()->add_parameters();
223	    param_proto->set_name(param.GetName());
224	    *param_proto->mutable_type() = param.GetType()->ToProto();
225	    return unwrapped;
226	  }
