  absl::Status InitProcDefChannels(
      const ProcDef* proc_def,
      const InterpValue::ProcInitializer& canonical_initializer,
      const TypeInfo* constructor_ti);
  absl::Status InitProcDefStateElements(
      const ProcDef* proc_def,
      const InterpValue::ProcInitializer& canonical_initializer);
