                              PackageInterfaceProto::FuzzTestDomain* proto);

  // Lowers a DSLX Tuple expression to a FuzzTestDomain proto.
  absl::Status LowerTupleExpr(XlsTuple* tuple_node,
                              PackageInterfaceProto::FuzzTestDomain* proto);
};

