90	// Tries to determine and return the entry function of the package.
91	// If package->top() is a function then that is returned. Otherwise, tries four
92	// heuristics as names for potential entry functions. Returns the first found
93	// heuristic. Otherwise, returns an absl::NotFoundError.
94	absl::StatusOr<xls::Function*> GetEntryFunction(xls::Package* package) {
95	  if (package->HasTop()) {
96	    xls::FunctionBase* top = package->GetTop().value();
97	    if (top->IsFunction()) {
98	      return top->AsFunctionOrDie();
99	    }
100	    // If top is defined but is not a function (i.e. it's a proc), it cannot be
101	    // returned as an xls::Function*.
102	    return absl::NotFoundError(absl::StrFormat(
103	        "Top entity in package '%s' is not a function.", package->name()));
104	  }
105	
106	  // The heuristics below for finding the entry function are for legacy
107	  // file-conversion paths where 'top' is not marked in the package. This logic
108	  // should be removed if the 'top' field is always set.
109	  constexpr char kMain[] = "main";
110	  // Try a few possibilities of names for the canonical entry function.
111	  const std::vector<std::string> to_try = {
112	      kMain,
113	      package->name(),
114	      absl::StrCat("__", package->name(), "__", kMain),
115	      absl::StrCat("__", package->name(), "__", package->name()),
116	  };
117	
118	  for (const std::string& attempt : to_try) {
119	    if (std::optional<xls::Function*> func = package->TryGetFunction(attempt);
120	        func.has_value()) {
121	      return *func;
122	    }
123	  }
124	
125	  std::vector<xls::Function*> functions;
126	  // Finally we use the only function if only one exists.
127	  for (xls::FunctionBase* fb : package->GetFunctionBases()) {
128	    if (fb->IsFunction()) {
129	      functions.emplace_back(fb->AsFunctionOrDie());
130	    }
131	  }
132	  if (functions.size() == 1) {
133	    return functions.front();
134	  }
135	
136	  return absl::NotFoundError(absl::StrFormat(
137	      "Could not find an entry function for the \"%s\" package.",
138	      package->name()));
139	}
