141	// As a postprocessing step for converting a module to a package, we check and
142	// see if the entry point has the "implicit token" calling convention, to see if
143	// it should be wrapped up.
144	//
145	// Note: we do this as a postprocessing step because we can't know what the
146	// module entry point is _until_ all functions have been converted.
147	absl::Status WrapEntryIfImplicitToken(const PackageData& package_data,
148	                                      ImportData* import_data,
149	                                      const ConvertOptions& options) {
150	  auto entry_point_not_found_handler =
151	      [](const absl::Status& status) -> absl::Status {
152	    XLS_RET_CHECK_EQ(status.code(), absl::StatusCode::kNotFound);
153	    return absl::OkStatus();
154	  };
155	
156	  XLS_ASSIGN_OR_RETURN(
157	      xls::Function * entry,
158	      GetEntryFunction(package_data.conversion_info->package.get()),
159	      _.With(entry_point_not_found_handler));
160	
161	  if (package_data.wrappers.contains(entry)) {
162	    // Already created!
163	    return absl::OkStatus();
164	  }
165	
166	  dslx::Function* dslx_entry =
167	      dynamic_cast<Function*>(package_data.ir_to_dslx.at(entry));
168	  XLS_RET_CHECK(dslx_entry != nullptr);
169	  if (GetRequiresImplicitToken(*dslx_entry, import_data, options)) {
170	    // Only create implicit token wrapper.
171	    auto implicit_entry_proto =
172	        absl::c_find_if(package_data.conversion_info->interface.functions(),
173	                        [&](const PackageInterfaceProto::Function& f) {
174	                          return f.base().name() == entry->name();
175	                        });
176	    return EmitImplicitTokenEntryWrapper(
177	               entry, dslx_entry,
178	               /*is_top=*/false, &package_data.conversion_info->interface,
179	               *implicit_entry_proto)
180	        .status();
181	  }
182	  return absl::OkStatus();
183	}
