185	absl::Status ConvertOneFunctionInternal(PackageData& package_data,
186	                                        const ConversionRecord& record,
187	                                        ImportData* import_data,
188	                                        ProcConversionData* proc_data,
189	                                        ChannelScope* channel_scope,
190	                                        const ConvertOptions& options) {
191	  VLOG(6) << "Convert record: " << record.ToString();
192	
193	  // Validate the requested conversion looks sound in terms of provided
194	  // parametrics.
195	  XLS_RETURN_IF_ERROR(ConversionRecord::ValidateParametrics(
196	      record.f(), record.parametric_env()));
197	
198	  FunctionConverter converter(package_data, record.module(), import_data,
199	                              options, proc_data, channel_scope,
200	                              record.IsTop());
201	  XLS_ASSIGN_OR_RETURN(
202	      auto constant_deps,
203	      GetConstantDepFreevars(record.f()->body(), *record.type_info()));
204	  for (const auto& dep : constant_deps) {
205	    converter.AddConstantDep(dep);
206	  }
207	
208	  if (record.proc_def().has_value()) {
209	    return converter.ConvertProcDef(
210	        *record.proc_def(), *record.init_value(), *record.proc_id(),
211	        record.config_record()->type_info(), record.type_info(),
212	        record.parametric_env());
213	  }
214	
215	  Function* f = record.f();
216	  if (f->is_test_utility() && !options.convert_tests) {
217	    return absl::InvalidArgumentError(absl::StrFormat(
218	        "Tried to convert a %s used in tests, but test conversion is disabled",
219	        f->IsInProc()
220	            ? absl::StrFormat("proc '%s'",
221	                              f->proc().value()->name_def()->identifier())
222	            : absl::StrFormat("function '%s'", f->identifier())));
223	  }
224	
225	  if (f->tag() == FunctionTag::kProcConfig) {
226	    XLS_RET_CHECK(!options.lower_to_proc_scoped_channels)
227	        << "Should not process config or init methods if "
228	           "lower_to_proc_scoped_channels set";
229	    // TODO(rspringer): 2021-09-29: Probably need to pass constants in here.
230	    ProcConfigIrConverter config_converter(
231	        f, record.type_info(), import_data, proc_data, channel_scope,
232	        record.parametric_env(), record.proc_id().value());
233	    XLS_RETURN_IF_ERROR(f->Accept(&config_converter));
234	    XLS_RETURN_IF_ERROR(config_converter.Finalize());
235	    return absl::OkStatus();
236	  }
237	
238	  if (f->tag() == FunctionTag::kProcNext) {
239	    if (!proc_data->id_to_initial_value.contains(record.proc_id().value()) &&
240	        (!options.lower_to_proc_scoped_channels || record.IsTop())) {
241	      // For proc scoped channels, we will defer the init evaluation to later.
242	      Proc* p = f->proc().value();
243	      // If there's no value in the map, then this should be a top-level proc.
244	      XLS_ASSIGN_OR_RETURN(
245	          InterpValue iv,
246	          ConstexprEvaluator::EvaluateToValue(
247	              import_data, record.type_info(), kNoWarningCollector,
248	              record.parametric_env(), p->init().body()));
249	      XLS_ASSIGN_OR_RETURN(Value ir_value, iv.ConvertToIr());
250	      proc_data->id_to_initial_value[record.proc_id().value()] = ir_value;
251	    }
252	
253	    return converter.HandleProcNextFunction(record, import_data, proc_data);
254	  }
255	
256	  return converter.HandleFunction(f, record.type_info(),
257	                                  &record.parametric_env());
258	}
