260	// Creates the recv- and send-only channels needed for the top-level proc - it
261	// needs to communicate with the outside world somehow.
262	absl::Status CreateBoundaryChannels(absl::Span<Param* const> params,
263	                                    const ProcId& proc_id, TypeInfo* type_info,
264	                                    ProcConversionData* proc_data,
265	                                    ChannelScope* channel_scope) {
266	  for (const Param* param : params) {
267	    TypeAnnotation* type = param->type_annotation();
268	    if (type->annotation_kind() == ChannelTypeAnnotation::kAnnotationKind) {
269	      XLS_ASSIGN_OR_RETURN(
270	          ChannelOrArray channel_or_array,
271	          channel_scope->DefineBoundaryChannelOrArray(param, type_info));
272	      proc_data->id_to_config_args[proc_id].push_back(
273	          ChannelOrArrayToProcConfigValue(channel_or_array));
274	    }
275	  }
276	  return absl::OkStatus();
277	}
