279	// Converts the functions in the call graph in a specified order.
280	//
281	// Args:
282	//   order: order for conversion
283	//   import_data: Contains type information used in conversion.
284	//   options: Conversion option flags.
285	//   package: output of function
286	absl::Status ConvertCallGraph(absl::Span<const ConversionRecord> order,
287	                              ImportData* import_data,
288	                              const ConvertOptions& options,
289	                              PackageData& package_data) {
290	  VLOG(3) << "Conversion order: [\n\t"
291	          << absl::StrJoin(
292	                 order, "\n\t",
293	                 [](std::string* out, const ConversionRecord& record) {
294	                   absl::StrAppend(out, record.ToString());
295	                 })
296	          << "\n]";
297	  // GetOrder() (in extract_conversion_order.h) handles evaluation ordering.
298	  // For procs, the config block must be evaluated before the next
299	  // block, as config sets channels and constants needed by next. This is
300	  // handled inside ConvertOneFunctionInternal().
301	  ProcConversionData proc_data;
302	
303	  // The `ChannelScope` owns all `ChannelArray` objects in the call graph, so
304	  // we need one instance to span all functions. However, most uses of it need
305	  // to be in the context of a proc, and it needs to be aware of the current
306	  // function context, for e.g. index expression interpretation.
307	  ChannelScope channel_scope(package_data.conversion_info, import_data,
308	                             options);
309	
310	  // The top-level proc's input/output channels need to come from _somewhere_.
311	  // At conversion time, though, we won't have that info. To enable forward
312	  // progress, we collect any channel args to the top-level proc and declare
313	  // them as send- or recv-only, as appropriate.
314	  const ConversionRecord* first_proc_config = nullptr;
315	  const ConversionRecord* first_proc_next = nullptr;
316	  Proc* top_proc = nullptr;
317	  // Only "next" functions are marked as "top", but we need to treat "config"
318	  // functions specially too, so we need to find the associated proc.
319	  for (const auto& record : order) {
320	    if (record.IsTop() && record.f()->tag() == FunctionTag::kProcNext) {
321	      top_proc = record.f()->proc().value();
322	    }
323	  }
324	
325	  // If there's no top proc, then we'll just do our best & pick the first one.
326	  if (top_proc == nullptr) {
327	    for (const auto& record : order) {
328	      if (record.f()->tag() == FunctionTag::kProcConfig) {
329	        top_proc = record.f()->proc().value();
330	        break;
331	      }
332	    }
333	  }
334	
335	  for (const auto& record : order) {
336	    if (record.f()->tag() == FunctionTag::kProcConfig &&
337	        record.f()->proc().value() == top_proc) {
338	      first_proc_config = &record;
339	    } else if (record.IsTop() && record.f()->tag() == FunctionTag::kProcNext) {
340	      first_proc_next = &record;
341	    }
342	
343	    if (first_proc_config != nullptr && first_proc_next != nullptr) {
344	      break;
345	    }
346	  }
347	
348	  // Set first proc's initial value.
349	  if (first_proc_config != nullptr) {
350	    XLS_RET_CHECK(first_proc_config->proc_id().has_value());
351	    ProcId proc_id = first_proc_config->proc_id().value();
352	    channel_scope.EnterFunctionContext(first_proc_config->type_info(),
353	                                       first_proc_config->parametric_env());
354	    XLS_RETURN_IF_ERROR(CreateBoundaryChannels(
355	        first_proc_config->f()->params(), proc_id,
356	        first_proc_config->type_info(), &proc_data, &channel_scope));
357	  }
358	
359	  for (const ConversionRecord& record : order) {
360	    VLOG(3) << "Converting to IR: " << record.ToString();
361	    channel_scope.EnterFunctionContext(record.type_info(),
362	                                       record.parametric_env());
363	    XLS_RETURN_IF_ERROR(ConvertOneFunctionInternal(package_data, record,
364	                                                   import_data, &proc_data,
365	                                                   &channel_scope, options));
366	  }
367	
368	  if (options.verify_ir) {
369	    VLOG(3) << "Verifying converted package";
370	    XLS_RETURN_IF_ERROR(
371	        VerifyPackage(package_data.conversion_info->package.get()));
372	  }
373	  return absl::OkStatus();
374	}
