376	absl::StatusOr<std::vector<ConversionRecord>> GetConversionRecords(
377	    Module* module, TypeInfo* type_info, const ConvertOptions& options) {
378	  // TODO: https://github.com/google/xls/issues/2078 - Remove this `if` after
379	  // lower_to_proc_scoped_channels is turned on everywhere, and call
380	  // GetConversionRecords unconditionally.
381	  if (options.lower_to_proc_scoped_channels) {
