404	absl::Status ConvertModuleIntoPackage(Module* module, ImportData* import_data,
405	                                      const ConvertOptions& options,
406	                                      PackageConversionData* package) {
407	  XLS_ASSIGN_OR_RETURN(TypeInfo * root_type_info,
408	                       import_data->GetRootTypeInfo());
409	  XLS_ASSIGN_OR_RETURN(std::vector<ConversionRecord> order,
410	                       GetConversionRecords(module, root_type_info, options));
411	  PackageData package_data{.conversion_info = package};
412	  XLS_RETURN_IF_ERROR(
413	      ConvertCallGraph(order, import_data, options, package_data));
414	
415	  XLS_RETURN_IF_ERROR(
416	      WrapEntryIfImplicitToken(package_data, import_data, options));
417	
418	  return absl::OkStatus();
419	}
