437	// Perform basic checks that the proc can be the top converted proc and create
438	// an appropriate error message if the proc is unacceptable.
439	//
440	// To be acceptable the proc must only have channels as its config arguments.
441	absl::Status CheckAcceptableTopProc(Proc* proc) {
442	  auto is_not_channel_param = [&](const Param* param) {
443	    return dynamic_cast<ChannelTypeAnnotation*>(param->type_annotation()) ==
444	           nullptr;
445	  };
446	  auto it = absl::c_find_if(proc->config().params(), is_not_channel_param);
447	  if (it != proc->config().params().end()) {
448	    return absl::InvalidArgumentError(absl::StrFormat(
449	        "Cannot convert proc '%s' due to non-channel config arguments: %s",
450	        proc->identifier(),
451	        absl::StrJoin(
452	            iter::imap(
453	                [](const Param* nd) -> std::string {
454	                  return absl::StrCat("'", nd->ToInlineString(), "'");
455	                },
456	                iter::filter(is_not_channel_param, proc->config().params())),
457	            ", ")));
458	  }
459	
460	  return absl::OkStatus();
461	}
