463	absl::Status CheckAcceptableTopProcDef(const ProcDef* proc, TypeInfo* ti) {
464	  if (!proc->impl().has_value()) {
465	    return absl::InvalidArgumentError(
466	        absl::Substitute("Cannot convert proc '$0' because it does not have an "
467	                         "impl with a constructor.",
468	                         proc->identifier()));
469	  }
470	
471	  return GetTopProcConstructor(proc, ti).status();
472	}
