498	absl::Status ConvertOneFunctionIntoPackage(Module* module,
499	                                           std::string_view entry_function_name,
500	                                           ImportData* import_data,
501	                                           const ParametricEnv* parametric_env,
502	                                           const ConvertOptions& options,
503	                                           PackageConversionData* conv) {
504	  absl::StatusOr<TestFunction*> test_fn = module->GetTest(entry_function_name);
505	  if (test_fn.ok()) {
506	    if (!options.convert_tests) {
507	      return absl::InvalidArgumentError(absl::StrFormat(
508	          "IR conversion of tests is disabled, but conversion of a test "
509	          "function \"%s\" from module %s was requested.",
510	          entry_function_name, module->name()));
511	    }
512	    return ConvertOneFunctionIntoPackageInternal(&(*test_fn)->fn(), import_data,
513	                                                 options, conv);
514	  }
515	  absl::StatusOr<FuzzTestFunction*> fuzz_test_fn =
516	      module->GetMemberOrError<FuzzTestFunction>(entry_function_name);
517	  if (fuzz_test_fn.ok()) {
518	    return ConvertOneFunctionIntoPackageInternal(&(*fuzz_test_fn)->fn(),
519	                                                 import_data, options, conv);
520	  }
521	
522	  std::optional<Function*> fn_or = module->GetFunction(entry_function_name);
523	  if (fn_or.has_value()) {
524	    if (fn_or.value()->is_test_utility() && !options.convert_tests) {
525	      return absl::InvalidArgumentError(absl::StrFormat(
526	          "IR conversion of tests is disabled, but conversion of a test "
527	          "utility function \"%s\" from module %s was requested.",
528	          entry_function_name, module->name()));
529	    }
530	
531	    return ConvertOneFunctionIntoPackageInternal(*fn_or, import_data, options,
532	                                                 conv);
533	  }
534	
535	  absl::StatusOr<TestProc*> test_proc =
536	      module->GetTestProc(entry_function_name);
537	  if (test_proc.ok()) {
538	    XLS_RETURN_IF_ERROR(CheckAcceptableTopProc((*test_proc)->proc()));
539	    if (!options.convert_tests) {
540	      return absl::InvalidArgumentError(
541	          absl::StrFormat("IR conversion of tests is disabled, but conversion "
542	                          "of a test proc \"%s\" from module %s was requested.",
543	                          entry_function_name, module->name()));
544	    }
545	    return ConvertOneFunctionIntoPackageInternal((*test_proc)->proc(),
546	                                                 import_data, options, conv);
547	  }
548	
549	  absl::StatusOr<Proc*> proc =
550	      module->GetMemberOrError<Proc>(entry_function_name);
551	  if (proc.ok()) {
552	    XLS_RETURN_IF_ERROR(CheckAcceptableTopProc(*proc));
553	    return ConvertOneFunctionIntoPackageInternal(*proc, import_data, options,
554	                                                 conv);
555	  }
556	
557	  absl::StatusOr<ProcDef*> proc_def =
558	      module->GetMemberOrError<ProcDef>(entry_function_name);
559	  if (proc_def.ok()) {
560	    XLS_ASSIGN_OR_RETURN(TypeInfo * ti, import_data->GetRootTypeInfo());
561	    XLS_RETURN_IF_ERROR(CheckAcceptableTopProcDef(*proc_def, ti));
562	    return ConvertOneFunctionIntoPackageInternal(*proc_def, import_data,
563	                                                 options, conv);
564	  }
565	
566	  absl::StatusOr<ProcAlias*> proc_alias =
567	      module->GetMemberOrError<ProcAlias>(entry_function_name);
568	  if (proc_alias.ok()) {
569	    XLS_ASSIGN_OR_RETURN(TypeInfo * ti, import_data->GetRootTypeInfo());
570	    ResolvedProcAlias resolved_alias = ti->GetResolvedProcAlias(*proc_alias);
571	    XLS_RETURN_IF_ERROR(CheckAcceptableTopProc(resolved_alias.proc));
572	    return ConvertOneFunctionIntoPackageInternal(
573	        resolved_alias.proc, import_data, options, conv, resolved_alias);
574	  }
575	
576	  return absl::InvalidArgumentError(
577	      absl::StrFormat("Entry \"%s\" is not present in "
578	                      "DSLX module %s as a Function or a Proc.",
579	                      entry_function_name, module->name()));
580	}
