595	absl::StatusOr<std::unique_ptr<Module>> ParseText(
596	    VirtualizableFilesystem& vfs, FileTable& file_table, std::string_view text,
597	    std::string_view module_name, bool print_on_error,
598	    std::string_view filename, bool* printed_error) {
599	  Fileno fileno = file_table.GetOrCreate(filename);
600	  Scanner scanner{file_table, fileno, std::string(text)};
601	  Parser parser(std::string(module_name), &scanner);
602	  absl::StatusOr<std::unique_ptr<Module>> module = parser.ParseModule();
603	  *printed_error = TryPrintError(module.status(), file_table, vfs);
604	  return module;
605	}
606	
607	absl::Status CheckPackageName(std::string_view name) {
608	  XLS_ASSIGN_OR_RETURN(std::vector<xls::Token> tokens, TokenizeString(name));
609	  if (tokens.size() != 1) {
610	    return absl::InvalidArgumentError(absl::StrFormat(
611	        "package name '%s' (len: %d) is not a valid package name and would "
612	        "fail to parse from text-ir. Avoid use of infix or special characters.",
613	        name, name.size()));
614	  }
615	  return absl::OkStatus();
616	}
617	
618	// Adds IR-converted symbols from the module specified by "path" to the given
619	// "package".
620	//
621	// TODO(leary): 2021-07-21 We should be able to reuse the type checking if
622	// there are overlapping nodes in the module DAG between files to process. For
623	// now we throw it away for each file and re-derive it (we need to refactor to
624	// make the modules outlive any given AddPathToPackage() if we want to
625	// appropriately reuse things in ImportData).
626	absl::Status AddContentsToPackage(
627	    std::string_view file_contents, std::string_view module_name,
628	    std::optional<std::string_view> path, std::optional<std::string_view> entry,
629	    const ConvertOptions& convert_options, ImportData* import_data,
630	    PackageConversionData* conv, bool* printed_error) {
631	  // Parse the module text.
632	  const std::string_view path_value = path.value_or("<UNKNOWN>");
633	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<Module> module,
634	                       ParseText(import_data->vfs(), import_data->file_table(),
635	                                 file_contents, module_name,
636	                                 /*print_on_error=*/true,
637	                                 /*filename=*/path_value, printed_error));
638	  XLS_RETURN_IF_ERROR(
639	      module->SetConfiguredValues(convert_options.configured_values));
640	  absl::StatusOr<TypecheckedModule> typechecked_module =
641	      TypecheckModule(std::move(module), path_value, import_data);
642	  if (!typechecked_module.ok()) {
643	    *printed_error =
644	        TryPrintError(typechecked_module.status(), import_data->file_table(),
645	                      import_data->vfs());
646	    return typechecked_module.status();
647	  }
648	
649	  WarningCollector& warnings = typechecked_module->warnings;
650	  if (convert_options.warnings_as_errors && !warnings.warnings().empty()) {
651	    *printed_error = true;
652	    PrintWarnings(warnings, import_data->file_table(), import_data->vfs());
653	    return absl::InvalidArgumentError(
654	        "Warnings encountered and warnings-as-errors set.");
655	  }
656	
657	  if (entry.has_value()) {
658	    XLS_RETURN_IF_ERROR(ConvertOneFunctionIntoPackage(
659	        typechecked_module->module, entry.value(), /*import_data=*/import_data,
660	        /*parametric_env=*/nullptr, convert_options, conv));
661	  } else {
662	    XLS_RETURN_IF_ERROR(ConvertModuleIntoPackage(
663	        typechecked_module->module, import_data, convert_options, conv));
664	  }
665	  return absl::OkStatus();
666	}
667	
668	}  // namespace
669	
670	absl::StatusOr<PackageConversionData> ConvertFilesToPackage(
671	    absl::Span<const std::string_view> paths, std::string_view stdlib_path,
672	    absl::Span<const std::filesystem::path> dslx_paths,
673	    const ConvertOptions& convert_options, std::optional<std::string_view> top,
674	    std::optional<std::string_view> package_name, bool* printed_error) {
675	  std::string resolved_package_name;
676	  if (package_name.has_value()) {
677	    resolved_package_name = package_name.value();
678	  } else {
679	    if (paths.size() > 1) {
680	      return absl::InvalidArgumentError(
681	          "Package name must be given when multiple input paths are supplied");
682	    }
683	    // Get it from the one module name (if package name was unspecified and we
684	    // just have one path).
685	    XLS_ASSIGN_OR_RETURN(resolved_package_name, PathToName(paths[0]));
686	  }
687	  XLS_RETURN_IF_ERROR(CheckPackageName(resolved_package_name));
688	  PackageConversionData conversion_data{
689	      .package = std::make_unique<xls::Package>(resolved_package_name)};
690	  *conversion_data.interface.mutable_name() = resolved_package_name;
691	  for (std::string_view p : paths) {
692	    *conversion_data.interface.add_files() = p;
693	  }
694	
695	  if (paths.size() > 1 && top.has_value()) {
696	    return absl::InvalidArgumentError(
697	        "Top cannot be supplied with multiple input paths (need a single input "
698	        "path to know where to resolve the entry function");
699	  }
700	  for (std::string_view path : paths) {
701	    ImportData import_data(
702	        CreateImportData(stdlib_path, dslx_paths, convert_options.warnings,
703	                         std::make_unique<RealFilesystem>()));
704	    XLS_ASSIGN_OR_RETURN(std::string text,
705	                         import_data.vfs().GetFileContents(path));
706	    XLS_ASSIGN_OR_RETURN(std::string module_name, PathToName(path));
707	    if (NameNeedsCanonicalization(path)) {
708	      WarningCollector col(convert_options.warnings);
709	      Pos pos(import_data.file_table().GetOrCreate(path), 0, 0);
710	      col.Add(
711	          Span(pos, pos), WarningKind::kIllegalPackageName,
712	          absl::StrFormat(
713	              "Module name '%s' is not a valid identifier name and "
714	              "would fail to parse from text-ir. Avoid use of "
715	              "infix or special characters.%s",
716	              RawNameFromPath(path).value(),
717	              convert_options.warnings_as_errors
718	                  ? ""
719	                  : absl::StrFormat(" Using '%s' as fallback.", module_name)));
720	      if (!col.empty()) {
721	        PrintWarnings(col, import_data.file_table(), import_data.vfs());
722	        if (convert_options.warnings_as_errors) {
723	          return absl::InvalidArgumentError(
724	              "Warnings encountered and warnings-as-errors set.");
725	        }
726	      }
727	    }
728	    bool dummy_printed_error = false;
729	    if (!printed_error) {
730	      printed_error = &dummy_printed_error;
731	    }
732	    XLS_RETURN_IF_ERROR(AddContentsToPackage(
733	        text, module_name, /*path=*/path, /*entry=*/top, convert_options,
734	        &import_data, &conversion_data, printed_error));
735	  }
736	  return conversion_data;
737	}
738	
739	}  // namespace xls::dslx
