1322	absl::Status FunctionConverter::HandleMatch(const Match* node) {
1323	  if (node->arms().empty()) {
1324	    return IrConversionErrorStatus(
1325	        node->span(),
1326	        "Only matches with complete patterns (i.e. a trailing `_ => ...`) "
1327	        "are currently supported for IR conversion.",
1328	        file_table());
1329	  }
1330	
1331	  if (node->IsConst()) {
1332	    return HandleConstMatch(node);
1333	  }
1334	
1335	  XLS_RETURN_IF_ERROR(Visit(node->matched()));
1336	  XLS_ASSIGN_OR_RETURN(BValue matched, Use(node->matched()));
1337	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<Type> matched_type,
1338	                       ResolveType(node->matched()));
1339	
1340	  std::vector<BValue> arm_selectors;
1341	  std::vector<BValue> arm_values;
1342	  for (int64_t i = 0; i < node->arms().size() - 1; ++i) {
1343	    MatchArm* arm = node->arms()[i];
1344	
1345	    // Visit all the MatchArm's patterns.
1346	    std::vector<BValue> this_arm_selectors;
1347	    for (const PatternTree& pattern : arm->patterns()) {
1348	      XLS_ASSIGN_OR_RETURN(BValue selector,
1349	                           HandleMatcher(pattern, matched, *matched_type));
1350	      XLS_RET_CHECK(selector.valid());
1351	      this_arm_selectors.push_back(selector);
1352	    }
1353	
1354	    // "Or" together the patterns in this arm, if necessary, to determine if the
1355	    // arm is selected.
1356	    if (this_arm_selectors.size() > 1) {
1357	      arm_selectors.push_back(function_builder_->AddNaryOp(
1358	          Op::kOr, this_arm_selectors, ToSourceInfo(arm->span())));
1359	    } else {
1360	      arm_selectors.push_back(this_arm_selectors[0]);
1361	    }
1362	
1363	    {
1364	      ScopedControlPredicate scp(
1365	          this, [&](const PredicateFun& orig_control_predicate) {
1366	            // This arm is "activated" when:
1367	            // * none of the previous arms have been selected
1368	            // * this arm is selected
1369	            // * the previously-established control predicate is true
1370	            auto prior_selectors = absl::MakeSpan(arm_selectors)
1371	                                       .subspan(0, arm_selectors.size() - 1);
1372	            BValue not_any_prev_selected;
1373	            if (prior_selectors.empty()) {
1374	              not_any_prev_selected = function_builder_->Literal(UBits(1, 1));
1375	            } else if (prior_selectors.size() == 1) {
1376	              not_any_prev_selected =
1377	                  function_builder_->Not(prior_selectors.front());
1378	            } else {
1379	              not_any_prev_selected = function_builder_->Nor(prior_selectors);
1380	            }
1381	            BValue this_arm_selected = arm_selectors.back();
1382	            return function_builder_->And({orig_control_predicate(),
1383	                                           not_any_prev_selected,
1384	                                           this_arm_selected});
1385	          });
1386	      XLS_RETURN_IF_ERROR(Visit(arm->expr()));
1387	    }
1388	
1389	    XLS_ASSIGN_OR_RETURN(BValue arm_rhs_value, Use(arm->expr()));
1390	    arm_values.push_back(arm_rhs_value);
1391	  }
1392	
1393	  // For compute of the default (last) arm the control predicate is "none of the
1394	  // other arms matched".
1395	  ScopedControlPredicate scp(
1396	      this, [&](const PredicateFun& orig_control_predicate) {
1397	        // The default arm is "activated" when:
1398	        // * none of the previous arms have been selected
1399	        // * the previously-established control predicate is true
1400	        auto prior_selectors = absl::MakeSpan(arm_selectors);
1401	        BValue not_any_prev_selected;
1402	        if (prior_selectors.empty()) {
1403	          not_any_prev_selected = function_builder_->Literal(UBits(1, 1));
1404	        } else if (prior_selectors.size() == 1) {
1405	          not_any_prev_selected =
1406	              function_builder_->Not(prior_selectors.front());
1407	        } else {
1408	          not_any_prev_selected = function_builder_->Nor(prior_selectors);
1409	        }
1410	        return function_builder_->And(
1411	            {orig_control_predicate(), not_any_prev_selected});
1412	      });
1413	
1414	  // We are guaranteed from exhaustiveness checking that the last arm handles
1415	  // all of the rest of the values aside from the ones covered by the earlier
1416	  // match arms, and so can be emitted as the "default" in the selection IR.
1417	  MatchArm* default_arm = node->arms().back();
1418	  XLS_RETURN_IF_ERROR(
1419	      HandleMatcher(default_arm->patterns()[0], matched, *matched_type)
1420	          .status());
1421	  XLS_RETURN_IF_ERROR(Visit(default_arm->expr()));
1422	
1423	  // So now we have the following representation of the match arms:
1424	  //   match x {
1425	  //     42  => a
1426	  //     64  => b
1427	  //     128 => d
1428	  //     _   => d
1429	  //   }
1430	  //
1431	  //   selectors:     [x==42, x==64, x==128]
1432	  //   values:        [a,         b,      c]
1433	  //   default_value: d
1434	  XLS_ASSIGN_OR_RETURN(BValue default_value, Use(default_arm->expr()));
1435	
1436	  if (arm_selectors.empty()) {
1437	    // If there are no case arms, there is only a default value, avoid emitting
1438	    // lots of junk operations like zero-bit concatenations via MatchTrue
1439	    // builder by just setting the node value to be the default value.
1440	    XLS_RET_CHECK(arm_values.empty());
1441	    SetNodeToIr(node, default_value);
1442	  } else {
1443	    BValue result =
1444	        function_builder_->MatchTrue(arm_selectors, arm_values, default_value);
1445	    XLS_RETURN_IF_ERROR(function_builder_->GetError());
1446	    SetNodeToIr(node, result);
1447	  }
1448	  return absl::OkStatus();
1449	}
