1451	absl::StatusOr<FunctionConverter::RangeData> FunctionConverter::GetRangeData(
1452	    const Expr* iterable) {
1453	  auto error = [&] {
1454	    return IrConversionErrorStatus(
1455	        iterable->span(),
1456	        absl::StrFormat("iterable `%s` "
1457	                        "must be bits-typed, constexpr, and its start must be "
1458	                        "less than or equal to its limit.",
1459	                        iterable->ToString()),
1460	        file_table());
1461	  };
1462	
1463	  // Easy case first: using the `..` range operator.
1464	  InterpValue start_value(InterpValue::MakeToken());
1465	  InterpValue limit_value(InterpValue::MakeToken());
1466	  ParametricEnv bindings(parametric_env_map_);
1467	
1468	  const auto* range_op = dynamic_cast<const Range*>(iterable);
1469	  bool inclusive_end = false;
1470	  if (range_op != nullptr) {
1471	    XLS_ASSIGN_OR_RETURN(
1472	        start_value, ConstexprEvaluator::EvaluateToValue(
1473	                         import_data_, current_type_info_, kNoWarningCollector,
1474	                         bindings, range_op->start()));
1475	    XLS_ASSIGN_OR_RETURN(
1476	        limit_value, ConstexprEvaluator::EvaluateToValue(
1477	                         import_data_, current_type_info_, kNoWarningCollector,
1478	                         bindings, range_op->end()));
1479	    inclusive_end = range_op->inclusive_end();
1480	  } else {
1481	    const auto* iterable_call = dynamic_cast<const Invocation*>(iterable);
1482	    if (iterable_call == nullptr) {
1483	      return error();
1484	    }
1485	    auto* callee_name_ref = dynamic_cast<NameRef*>(iterable_call->callee());
1486	    if (callee_name_ref == nullptr) {
1487	      return error();
1488	    }
1489	    if (!std::holds_alternative<BuiltinNameDef*>(callee_name_ref->name_def())) {
1490	      return error();
1491	    }
1492	    auto* builtin_name_def =
1493	        std::get<BuiltinNameDef*>(callee_name_ref->name_def());
1494	    if (builtin_name_def->identifier() != "range") {
1495	      return error();
1496	    }
1497	
1498	    XLS_RET_CHECK_EQ(iterable_call->args().size(), 2);
1499	    Expr* start = iterable_call->args()[0];
1500	    Expr* limit = iterable_call->args()[1];
1501	
1502	    XLS_ASSIGN_OR_RETURN(
1503	        start_value, ConstexprEvaluator::EvaluateToValue(
1504	                         import_data_, current_type_info_, kNoWarningCollector,
1505	                         bindings, start));
1506	    XLS_ASSIGN_OR_RETURN(
1507	        limit_value, ConstexprEvaluator::EvaluateToValue(
1508	                         import_data_, current_type_info_, kNoWarningCollector,
1509	                         bindings, limit));
1510	  }
1511	
1512	  if (!start_value.IsBits() || !limit_value.IsBits()) {
1513	    return error();
1514	  }
1515	
1516	  XLS_ASSIGN_OR_RETURN(int64_t start_int, start_value.GetBitValueViaSign());
1517	  XLS_ASSIGN_OR_RETURN(int64_t bit_width, start_value.GetBitCount());
1518	
1519	  XLS_ASSIGN_OR_RETURN(InterpValue start_gt_limit, start_value.Gt(limit_value));
1520	  if (start_gt_limit.IsTrue()) {
1521	    return RangeData{start_int, 0, bit_width};
1522	  }
1523	
1524	  XLS_ASSIGN_OR_RETURN(InterpValue trip_count, limit_value.Sub(start_value));
1525	  if (inclusive_end) {
1526	    trip_count = InterpValue::MakeUnsigned(trip_count.GetBitsOrDie());
1527	    XLS_ASSIGN_OR_RETURN(trip_count,
1528	                         trip_count.IncrementZeroExtendIfOverflow());
1529	  }
1530	  XLS_RET_CHECK(trip_count.IsBits());
1531	  int64_t trip_count_int;
1532	  if (trip_count.IsSigned()) {
1533	    XLS_ASSIGN_OR_RETURN(trip_count_int, trip_count.GetBitValueViaSign());
1534	  } else {
1535	    XLS_ASSIGN_OR_RETURN(trip_count_int, trip_count.GetBitValueViaSign());
1536	  }
1537	
1538	  return RangeData{start_int, trip_count_int, bit_width};
1539	}
