571	                                         const AstNode* to) {
572	  XLS_RET_CHECK_NE(from, to);
573	  auto it = node_to_ir_.find(from);
574	  if (it == node_to_ir_.end()) {
575	    return absl::InternalError(absl::StrFormat(
576	        "TypeAliasError: %s internal error during IR conversion: could not "
577	        "find AST node for aliasing: `%s` (%s) to: `%s` (%s)",
578	        SpanToString(from->GetSpan(), file_table()), from->ToString(),
579	        from->GetNodeTypeName(), to->ToString(), to->GetNodeTypeName()));
580	  }
581	  IrValue value = it->second;
582	  VLOG(6) << absl::StreamFormat(
583	      "Aliased node '%s' (%s) to be same as '%s' (%s): %s", to->ToString(),
584	      to->GetNodeTypeName(), from->ToString(), from->GetNodeTypeName(),
585	      IrValueToString(value));
586	  node_to_ir_[to] = std::move(value);
587	  if (const auto* name_def = dynamic_cast<const NameDef*>(to)) {
588	    // Name the aliased node based on the identifier in the NameDef.
589	    IrValue from_ir_value = node_to_ir_.at(from);
590	    if (std::holds_alternative<BValue>(from_ir_value)) {
591	      BValue ir_node = std::get<BValue>(from_ir_value);
592	      XLS_RET_CHECK(ir_node.valid());
593	      if (ir_node.node()->op() != Op::kParam) {
594	        ir_node.SetName(name_def->identifier());
595	      }
596	    } else if (std::holds_alternative<CValue>(from_ir_value)) {
597	      BValue ir_node = std::get<CValue>(from_ir_value).value;
598	      XLS_RET_CHECK(ir_node.valid());
599	      if (ir_node.node()->op() != Op::kParam) {
600	        ir_node.SetName(name_def->identifier());
601	      }
602	    }
603	    // Do nothing for channels; they have no BValue-type representation (they
604	    // exist as _global_ entities, not nodes in a Proc's IR), so they can't
605	    // be [re]named.
606	  }
607	  return absl::OkStatus();
608	}
